import unittest

def average(values):
    if not values:
        raise ValueError("No measurements")
    return sum(values) / len(values)

class AverageTests(unittest.TestCase):
    def test_known_values(self):
        self.assertEqual(average([2, 4, 6]), 4)
    def test_empty(self):
        with self.assertRaises(ValueError):
            average([])

