def freshness(now_s, stamp_s, max_age_s=2.0):
    if stamp_s is None:
        return "missing"
    age_s = now_s - stamp_s
    if age_s < 0:
        return "invalid_time"
    return "stale" if age_s > max_age_s else "fresh"

print(freshness(10.0, 8.0))

