struct ring { int data[4]; size_t head; size_t count; };
bool ring_push(struct ring *q, int value) {
    if (q == NULL || q->head >= 4 || q->count >= 4) return false;
    q->data[(q->head + q->count) % 4] = value;
    ++q->count;
    return true;
}

